@app.cell
def _(imag_mat, mo, phase, real_mat):
    import numpy as np
    import matplotlib.pyplot as plt
    import pandas as pd
    from matplotlib.animation import FuncAnimation
    try:
        import utils.plot_settings_screen
    except ImportError:
        pass

    # Extract real and imaginary parts as 1x5 lists for mo.ui.matrix
    # UI Inputs for Re and Im parts
    elephant_title = mo.md('## Drawing and elementary animation of an elephant using Fourier series')

    matrix = mo.hstack([
        real_mat,
        imag_mat,
    ],align='center')
    p = np.array(real_mat.value[0]) + 1j * np.array(imag_mat.value[0])
    phase_val = phase.value
    def fourier(t, a, b):
        k = np.arange(len(a))[:, None]
        return np.sum(a[:, None] * np.cos(k * t) + b[:, None] * np.sin(k * t), axis=0)



    def elephant(p0, p1, p2, p3, p4, phase=0):
        """
        Generates elephant Fourier coordinates using 5 complex parameters p0-p4.
        p4.real controls the trunk wiggling amplitude, p4.imag sets the eye location.
        """
        ax = np.array([0, 0, 0, p2.real, 0, p3.real])
        bx = np.array([0, p0.real, p1.real, 0, 0, 0])
        ay = np.array([0, p3.imag, 0, 0, 0, 0])
        by = np.array([0, p0.imag, p1.imag, p2.imag, 0, 0])

        t1 = np.linspace(0.4 + 1.3 * np.pi, 2 * np.pi + 0.9 * np.pi, 400)
        t2 = np.linspace(2 * np.pi + 0.9 * np.pi, 0.4 + 3.3 * np.pi, 400)

        x1, y1 = fourier(t1, ax, bx), fourier(t1, ay, by)
        x2, y2 = fourier(t2, ax, bx), fourier(t2, ay, by)

        # Apply 5th parameter effects
        x2 = x2 + np.sin((y2 - y2[0]) * np.pi / 1000) * np.sin(phase) * p4.real
        eye = (-p4.imag, -p4.imag)

        return y1, -x1, y2, -x2, eye

    # Static 4-parameter elephant
    print(p)
    y1, x1, y2, x2, eye = elephant(*p,phase=phase_val)

    fig=plt.figure()#figsize=(4, 4))
    plt.plot(y1, x1, "k", lw=2)
    plt.plot(y2, x2, "k", lw=2)
    plt.plot(*eye,'ko',markersize=5)
    plt.axis("equal")
    plt.axis("off")
    # plt.title("4-parameter elephant")

    mo.vstack([elephant_title,matrix,phase,fig], align='center',justify='end')
    return np, pd, plt


