@app.cell
def _(deg_md, degree, mo, np, plt):
    # Small noisy dataset
    np.random.seed(1)
    x_train = np.linspace(0, 1, 10)
    y_train = np.sin(2 * np.pi * x_train) + 0.2 * np.random.randn(len(x_train))

    # New points to test generalization
    x_test = np.linspace(0, 1, 200)
    y_test = np.sin(2 * np.pi * x_test)

    # Two models: simple and overly complex
    p_simple = np.polyfit(x_train, y_train, 3)
    p_overfit = np.polyfit(x_train, y_train, degree.value)

    y_simple = np.polyval(p_simple, x_test)
    y_overfit = np.polyval(p_overfit, x_test)

    mse_simple = np.mean((y_simple - y_test) ** 2)
    mse_overfit = np.mean((y_overfit - y_test) ** 2)

    fig_over = plt.figure(figsize=(8,4))
    plt.scatter(x_train, y_train, color="black", label="training data")
    plt.plot(x_test, y_test, "k-", label="true function")
    plt.plot(x_test, y_simple, label="degree 3 fit")
    plt.plot(x_test, y_overfit, label=f"degree {degree.value} fit")
    # put legend above the plot
    plt.legend(ncol=2, loc="lower center", bbox_to_anchor=(0.5, 1.01))
    plt.xlabel("x")
    plt.ylabel("y")
    plt.xlim([-0.1,1.1])
    plt.ylim([-1.2,1.2])
    plt.text(x=0.5,y=0.5,s=f"Degree 3: MSE = {mse_simple:.3f}\nDegree {degree.value}: MSE = {mse_overfit:.3f}",fontsize=14)
    mo.vstack([deg_md,fig_over], align='center')
    return


