@app.cell
def _(mo, multiselect, np, pd, plt):
    from scipy.optimize import curve_fit
    from sklearn.metrics import mean_squared_error
    from scipy.integrate import odeint

    # import some data 
    data = pd.read_csv('./data/simple_physics.txt',sep=r'\s+')  # Assuming you have a CSV file with your data
    t = data['t'].values  # Use the x values from the CSV file
    PL = data['y'].values  # Use the y values from the CSV file  

    # Exponential fitting
    def exp_func(t, a, b):
        return a * np.exp(b * t)

    popt_exp, pcov_exp = curve_fit(exp_func, t, PL, p0=(1, -1))
    MSE_exp = mean_squared_error(PL, exp_func(t, *popt_exp))

    # ODE 1
    def model(y, x, b):
        """The ODE: dy/dx = b * y"""
        return b * y

    def ode_fit_func(x_points, a, b):
        """
        Wrapper function for curve_fit. 
        It takes the parameters a (initial condition) and b (rate),
        solves the ODE over x_points, and returns the 1D array of results.
        """
        # odeint requires the initial condition and the evaluation points
        y_sol = odeint(model, a, x_points, args=(b,))
        return y_sol.flatten()

    # ODE 2  with c * y**2
    def model2(y, x, b, c):
        """The ODE: dy/dx = b * y + c * y**2"""
        return b * y + c * y**2

    def ode_fit_func2(x_points, a, b, c):
        """
        Wrapper function for curve_fit for the second ODE. 
        It takes the parameters a (initial condition), b (rate), and c (nonlinear term),
        solves the ODE over x_points, and returns the 1D array of results.
        """
        y_sol = odeint(model2, a, x_points, args=(b, c))
        return y_sol.flatten()

    fig_fit = plt.figure(figsize=(7,5))
    plt.scatter(t, PL, color='k', label="data", zorder=-1)
    md_lst = []
    if "Exponential" in multiselect.value:
        plt.plot(t, exp_func(t, *popt_exp), label=f"Expo.", alpha=0.7, linewidth=3) 
        md_lst.append(
            mo.md(rf"""**Exponential decay:**  
                $n(t) = a \exp(bt)$  
                MSE = {MSE_exp:.2e}  
                a = {popt_exp[0]:.2f}  b = {popt_exp[1]:.2f}"""))
    if "ODE 1" in multiselect.value:
        popt_ode, pcov_ode = curve_fit(ode_fit_func, t, PL, p0=(1, -1))
        plt.plot(t, ode_fit_func(t, *popt_ode), ':', linewidth=3, label = 'ODE 1')
        MSE_ode = mean_squared_error(PL, ode_fit_func(t, *popt_ode))
        md_lst.append(
            mo.md(
        rf"""**ODE 1:**   
        $\frac{{dn}}{{dt}} = b \times n$  
        MSE = {MSE_ode:.2e}  
        a = {popt_ode[0]:.2f} b = {popt_ode[1]:.2f}     
        """))
    if "ODE 2" in multiselect.value:
        popt_ode2, pcov_ode2 = curve_fit(ode_fit_func2, t, PL, p0=(1, -1, 0.1))
        MSE_ode2 = mean_squared_error(PL, ode_fit_func2(t, *popt_ode2))
        plt.plot(t, ode_fit_func2(t, *popt_ode2), '--', label=f"ODE 2", linewidth=3)
        md_lst.append(
            mo.md(
                rf"""**ODE 2:**  
                $\frac{{dn}}{{dt}} = b n + c n^2$  
                MSE = {MSE_ode2:.2e}   
                a = {popt_ode2[0]:.2f} b = {popt_ode2[1]:.2f} c = {popt_ode2[2]:.2f}"""))
    plt.legend()
    plt.xlabel("t")
    plt.ylabel("PL")
    # plt.title("Some noisy decay data")
    stacking_mds = mo.vstack(md_lst,gap = 0)
    mo.vstack([multiselect,mo.hstack([fig_fit,stacking_mds])],align='center',gap = 0)
    return


